'use strict';

var test = require('tape');
var parse = require('../').parse;

test('set env vars', function (t) {
	t.same(
		parse('ABC= x y z'),
		['ABC=', 'x', 'y', 'z']
	);
	t.same(
		parse('ABC=\\ \\  x y z'),
		['ABC=  ', 'x', 'y', 'z']
	);
	t.same(
		parse('X="  " printx'),
		['X=  ', 'printx']
	);
	t.same(
		parse('X="  "; printx'),
		['X=  ', { op: ';' }, 'printx']
	);
	t.same(
		parse('X="  "; printx', function () {
			t.fail('should not have matched any keys');
		}),
		['X=  ', { op: ';' }, 'printx']
	);

	t.end();
});
